 56	func (c *simpleCache[K, V]) AddWithTTL(key K, value V, ttl time.Duration) error {
 57		c.evictExpired()
 58	
 59		item := c.data.Set(key, value, ttl)
 60		if item == nil {
 61			return errors.New("failed to add item")
 62		}
 63		c.scheduleEviction(item)
 64		return nil
 65	}
