 67	func (c *simpleCache[K, V]) Get(key K) (V, error) {
 68		c.evictExpired()
 69	
 70		item := c.data.Get(key)
 71		if item == nil {
 72			var zero V
 73			return zero, errors.New("item not found")
 74		}
 75		return item.Value(), nil
 76	}
