 78	func (c *simpleCache[K, V]) GetWithLoader(key K, loader func(key K) (V, time.Duration, error)) (V, error) {
 79		c.evictExpired()
 80	
 81		var loadErr error
 82		loaderWrapper := ttlcache.LoaderFunc[K, V](
 83			func(t *ttlcache.Cache[K, V], key K) *ttlcache.Item[K, V] {
 84				value, ttl, err := loader(key)
 85				if err != nil {
 86					loadErr = err
 87					return nil
 88				}
 89	
 90				c.evictExpired()
 91				item := t.Set(key, value, ttl)
 92				c.scheduleEviction(item)
 93				return item
 94			},
 95		)
 96		item := c.data.Get(key, ttlcache.WithLoader[K, V](loaderWrapper))
 97		if item == nil {
 98			var zero V
 99			if loadErr != nil {
100				return zero, loadErr
101			}
102			return zero, errors.New("item not found")
103		}
104		return item.Value(), nil
105	}
