107	func (c *simpleCache[K, V]) Keys() []K {
108		c.evictExpired()
109	
110		keys := make([]K, 0)
111		c.data.Range(func(item *ttlcache.Item[K, V]) bool {
112			if !item.IsExpired() {
113				keys = append(keys, item.Key())
114			}
115			return true
116		})
117		return keys
118	}
