121		c.evictExpired()
122	
123		values := make([]V, 0)
124		c.data.Range(func(item *ttlcache.Item[K, V]) bool {
125			if !item.IsExpired() {
126				values = append(values, item.Value())
127			}
128			return true
129		})
130		return values
131	}
