133	// evictExpired removes expired items when the next known expiration is due.
134	// The deadline avoids scanning the cache on every operation when all items
135	// are still active.
136	func (c *simpleCache[K, V]) evictExpired() {
137		c.evictionMu.Lock()
138		defer c.evictionMu.Unlock()
139	
140		deadline := c.evictionDeadline.Load()
141		if deadline == nil || time.Now().Before(*deadline) {
142			return
143		}
144	
145		c.data.DeleteExpired()
146	
147		var nextDeadline time.Time
148		c.data.Range(func(item *ttlcache.Item[K, V]) bool {
149			expiresAt := item.ExpiresAt()
150			if !expiresAt.IsZero() && (nextDeadline.IsZero() || expiresAt.Before(nextDeadline)) {
151				nextDeadline = expiresAt
152			}
153			return true
154		})
155	
156		if nextDeadline.IsZero() {
157			c.evictionDeadline.Store(nil)
158		} else {
159			c.evictionDeadline.Store(&nextDeadline)
160		}
161	}
162	
163	func (c *simpleCache[K, V]) scheduleEviction(item *ttlcache.Item[K, V]) {
164		if item == nil {
165			return
166		}
167	
168		expiresAt := item.ExpiresAt()
169		if expiresAt.IsZero() {
170			return
171		}
172	
173		c.evictionMu.Lock()
174		defer c.evictionMu.Unlock()
175	
176		deadline := c.evictionDeadline.Load()
177		if deadline == nil || expiresAt.Before(*deadline) {
178			c.evictionDeadline.Store(&expiresAt)
179		}
180	}
